#include <bits/stdc++.h>

using namespace std;

#define pii pair<int, int>
#define MP make_pair
#define LL long long
#define LEFT (i << 1)
#define RIGHT (LEFT | 1)
#define MID (ll + rr >> 1)
#define LEFT_RANGE ll, MID, LEFT
#define RIGHT_RANGE MID + 1, rr, RIGHT
#define EPS 1e-8
#define INF 0x3f3f3f3f
#define MOD 1000000007
#define MAXN 410
#define MAXM 200020
#define F first
#define S second

char buffer[32000000],*ptr=buffer,*output=buffer;
int readInt(){
    int sign=1, val=0;
    while((*ptr != '-') && (*ptr < '0' || *ptr > '9')) ptr++;
    if(*ptr=='-') sign=-1, ptr++;
    else val=*ptr++ - '0';
    while(*ptr>='0' && *ptr<='9') val=val*10+(*ptr++ - '0');
    return val*sign;
}
char readChar(){
    char ch;
    while(*ptr<'A' || *ptr>'Z') ptr++;
    ch=*ptr; ptr++;
    return ch;
}

struct FlowNetwork{
	int head[MAXN], v[M], nxt[M], capacity[M], flow[M], edgeCount;
	int dist[MAXN], current[MAXN];
	int source, sink;
	void initialize(){
		memset(head, -1, sizeof head); edgeCount=0;
	}
	void addEdge(int u, int v, int c){
		v[M]=v; nxt[M]=head[u]; capacity[M]=c; flow[M]=0; head[u]=edgeCount++;
		v[M]=u; nxt[M]=head[v]; capacity[M]=0; flow[M]=0; head[v]=edgeCount++;
	}
	bool buildLevelGraph(){
		memset(dist, -1, sizeof dist);
		dist[source]=0;
		queue<int> q;
		q.push(source);
		while(!q.empty()){
			int u=q.front(); q.pop();
			for(int i=head[u]; ~i; i=nxt[i]){
				int v=v[i];
				if(dist[v]==-1 && capacity[i]>flow[i]){
					dist[v]=dist[u]+1;
					q.push(v);
				}
			}
		}
		return dist[sink]!=-1;
	}
	int sendFlow(int u, int flowIn){
		if(u==sink || flowIn==0) return flowIn;
		int totalFlow=0, pushed;
		for(int &i=current[u]; ~i; i=nxt[i]){
			int v=v[i];
			if(dist[v]==dist[u]+1 && (pushed=sendFlow(v, min(flowIn, capacity[i]-flow[i])))>0){
				flow[i]+=pushed;
				flow[i^1]-=pushed;
				flowIn-=pushed;
				totalFlow+=pushed;
				if(flowIn==0) break;
			}
		}
		return totalFlow;
	}
	int maxFlow(int s, int t){
		source=s; sink=t;
		int total=0;
		while(buildLevelGraph()){
			memcpy(current, head, sizeof head);
			total+=sendFlow(s, INF);
		}
		return total;
	}
}net;
int dir[4][2]={{-1,0},{0,1},{1,0},{0,-1}};
int distMap[12][12], timeMap[12][12];
char grid[N][N], heatMap[N][N];
int n, t;
bool valid(int x, int y){
	return x>=0 && x<n && y>=0 && y<n;
}
void findObstacles(int sx, int sy){
	memset(timeMap, 0x3f, sizeof timeMap);
	queue<int> q;
	q.push(sx*10+sy);
	timeMap[sx][sy]=0;
	while(!q.empty()){
		int x=q.front()/10, y=q.front()%10;
		q.pop();
		for(int i=0; i<4; ++i){
			int nx=x+dir[i][0], ny=y+dir[i][1];
			if(valid(nx, ny) && grid[nx][ny]>='0' && grid[nx][ny]<='9' && timeMap[nx][ny]>timeMap[x][y]+1){
				timeMap[nx][ny]=timeMap[x][y]+1;
				q.push(nx*10+ny);
			}
		}
	}
}
void findHeatSources(int sx, int sy){
	memset(distMap, 0x3f, sizeof distMap);
	queue<int> q;
	q.push(sx*10+sy);
	distMap[sx][sy]=0;
	while(!q.empty()){
		int x=q.front()/10, y=q.front()%10;
		q.pop();
		for(int i=0; i<4; ++i){
			int nx=x+dir[i][0], ny=y+dir[i][1];
			if(valid(nx, ny) && heat[nx][ny]>='0' && heat[nx][ny]<='9' && distMap[nx][ny]>distMap[x][y]+1){
				if(heat[nx][ny]>='0' && timeMap[nx][ny]>=distMap[x][y]+1){
					distMap[nx][ny]=distMap[x][y]+1;
					if(timeMap[nx][ny]>distMap[nx][ny])
						q.push(nx*10+ny);
				}
			}
		}
	}
}
int main(){
	scanf("%d%d", &n, &t);
	for(int i=0; i<n; ++i)
		scanf("%s", grid[i]);
	for(int i=0; i<n; ++i)
		scanf("%s", heat[i]);
	for(int i=0; i<n; ++i)
		for(int j=0; j<n; ++j)
			if(grid[i][j]=='Z')
				findObstacles(i, j);
	int S=0, T=n*n*2+1;
	net.initialize();
	for(int i=0; i<n; ++i)
		for(int j=0; j<n; ++j){
			if(grid[i][j]>'0' && grid[i][j]<='9')
				net.addEdge(S, i*n+j+1, grid[i][j]-'0');
			if(heat[i][j]>'0' && heat[i][j]<='9')
				net.addEdge(n*n+i*n+j+1, T, heat[i][j]-'0');
		}
	for(int i=0; i<n; ++i)
		for(int j=0; j<n; ++j)
			if(grid[i][j]>'0' && grid[i][j]<='9'){
				findHeatSources(i, j);
				for(int x=0; x<n; ++x)
					for(int y=0; y<n; ++y){
						if(heat[x][y]>'0' && heat[x][y]<='9' && distMap[x][y]<=t){
							net.addEdge(i*n+j+1, n*n+x*n+y+1, INF);
						}
					}
			}
	int res=net.maxFlow(S, T);
	printf("%d\n", res);
	return 0;
}
